/*
 * Qué día hay que consultar.
 *
 * Ayer, salvo los lunes que va a hoy-2 para levantar el sábado. Los domingos no
 * se corre: no hubo jornada.
 *
 * La fecha se arma con getters locales y no con toISOString(), que devuelve UTC:
 * corriendo a las 8 de la mañana en Argentina las dos coinciden, pero si el
 * horario del schedule se moviera, UTC podría caer en el día siguiente.
 */
const hoy = new Date();
const dia = hoy.getDay();

if (dia === 0) return [{ json: { ejecutar: false } }];

const consulta = new Date(hoy);
consulta.setDate(hoy.getDate() - (dia === 1 ? 2 : 1));

const fechaSQL = [
  consulta.getFullYear(),
  String(consulta.getMonth() + 1).padStart(2, '0'),
  String(consulta.getDate()).padStart(2, '0'),
].join('-');

return [{ json: { ejecutar: true, fechaSQL } }];

/*
 * Pasa la salida de SQL Server a los nombres de columna de Postgres.
 *
 * Las fechas se formatean SIEMPRE con getters UTC. El flujo viejo mezclaba
 * `toISOString()` para la fecha con `toLocaleTimeString()` para la hora, que usa
 * la zona del servidor: cerca de medianoche las dos mitades se contradecían.
 */
const fecha = (v) => (v ? new Date(v).toISOString().slice(0, 10) : null);
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};

return $input.all().map(({ json: r }) => ({
  json: {
    id: Number(r.Id),
    fecha_creacion: fecha(r.FechaCreacion),
    fecha_programado: fecha(r.FechaProgramado),
    estado: texto(r.Estado),
    repartidor: texto(r.Repartidor),
    tienda: texto(r.Tienda),
    destino: texto(r.Destino),
    poligono: texto(r.Poligono),
    visitas: Number.isFinite(Number(r.Visitas)) ? Number(r.Visitas) : null,
  },
})).filter((i) => Number.isFinite(i.json.id) && i.json.id > 0);

/*
 * Cancelados a columnas de la base.
 *
 * Las dos fechas ya vienen con las 3 horas restadas por la consulta, así que son
 * hora local de México. Se formatean con getters UTC para conservar exactamente
 * ese reloj de pared: la columna en Postgres es `timestamp` sin zona, y aplicar
 * una segunda conversión las correría de nuevo.
 */
const marca = (v) => (v ? new Date(v).toISOString().slice(0, 19).replace('T', ' ') : null);
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};

return $input.all().map(({ json: r }) => ({
  json: {
    id: Number(r.Id),
    id_meli: texto(r.Id_MELI),
    tienda: texto(r.Tienda),
    estado_rbp: texto(r.Estado_RBP),
    estado_meli: texto(r.Estado_MELI),
    fecha_colectado: marca(r.Fecha_Colectado),
    fecha_cancelado: marca(r.Fecha_Cancelado),
  },
})).filter((i) => Number.isFinite(i.json.id) && i.json.id > 0);
